package com.company.tpm.score;import java.math.BigDecimal;import org.junit.jupiter.api.*;class ScoreServiceTest{private final ScoreService s=new ScoreService();@Test void calculatesPass(){var r=s.calculate(new BigDecimal("86"),new BigDecimal("100"),new BigDecimal("50"));Assertions.assertEquals(new BigDecimal("86.00"),r.percentage());Assertions.assertTrue(r.passed());}@Test void rejectsOutOfRange(){Assertions.assertThrows(IllegalArgumentException.class,()->s.calculate(new BigDecimal("101"),new BigDecimal("100"),new BigDecimal("50")));}}
